import"./modulepreload-polyfill-Dezn_h7o.js";/* empty css               */import"./proteger-pagina-CCLhLS-N.js";import{t as e}from"./config-DPSuE5lU.js";document.querySelector(`#cadastro-form`).addEventListener(`submit`,async t=>{t.preventDefault();let n=document.querySelector(`#firstname`).value,r=document.querySelector(`#lastname`).value,i=document.querySelector(`#email`).value,a=document.querySelector(`#password`).value;if(a.length<6){alert(`A senha deve ter pelo menos 6 caracteres.`);return}try{let t=await fetch(`${e}/cadastro`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify({nome:n,sobrenome:r,email:i,senha:a})});if(t.ok)alert(`Usuário cadastrado com sucesso!`),window.location.href=`/index.html`;else{let e=await t.json();alert(`Erro: ${e.message}`)}}catch(e){console.error(`Erro ao enviar a requisição:`,e),alert(`Erro ao conectar ao servidor.`)}});